            after = base64.urlsafe_b64decode(cursor.encode()).decode()
        except (ValueError, UnicodeDecodeError):
            return problem(400, "Invalid cursor")

    # Cursor is the last invoice id of the previous page; ids give a stable order.
    invoices = sorted(
        (i for i in _INVOICES.values() if i.customer_id == customer_id),
        key=lambda i: i.id,
    )
